typedef unsigned long long big_int;

class stringx;
class string_buf
{
  friend class stringx;
  friend stringx operator+( const stringx& lhs, const char* rhs );
  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx
{
  friend stringx operator+( const stringx& lhs, const char* rhs );
protected:
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx &cp);
  ~stringx();
  inline int size() const { return my_buf->char_length; }
  inline int length() const { return size(); }
  void make_room(int size);
  void append(const stringx& s);
  void append(const char *s, int len = -1);
  void to_lower();
};

extern "C" int strlen(const char *);
inline stringx operator+( const stringx& lhs, const char* rhs )
{
  stringx foo;
  int len = strlen(rhs);

  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);

  return foo;
}

class vm_executable;
class vm_thread;
class script_object
{
public:
  class instance
  {
  public:
    vm_thread* add_thread(const vm_executable* ex);
    void run_single_thread(vm_thread* t, bool ignore_suspended);
  };
  const vm_executable& get_func(int i) const;
  int find_func(const stringx& func_fullname) const;
};

class world_dynamics_system
{
public:
  script_object* get_current_level_global_script_object() const;
  script_object::instance* get_current_level_global_script_object_instance() const;
};
extern world_dynamics_system *g_world_ptr;

class entity
{
public:
  static void exec_preload_function(const stringx &preload_func);
};

void entity::exec_preload_function(const stringx &preload_func)
{
  if(preload_func.length() > 0)
  {
    // there might be a script function for preloading additional assets needed by item
    stringx preload_func_name = preload_func + "()";
    preload_func_name.to_lower();

    script_object* gso = g_world_ptr->get_current_level_global_script_object();
    int fidx = gso->find_func( preload_func_name );
    if ( fidx >= 0 )
    {
      script_object::instance* gsoi = g_world_ptr->get_current_level_global_script_object_instance();
      // spawn thread for function
      vm_thread* newt = gsoi->add_thread( &gso->get_func(fidx) );
      // run the NEW thread immediately
      gsoi->run_single_thread( newt, false );
    }
  }
}
